//! Renders each fixture and compares it with GIMP's own flattened PNG.
//! Fixtures are regenerated by scripts/xcf/gen.sh (see there).

use image::{imageops, RgbaImage};
use std::time::{Duration, Instant};
use fractale::model::thumbs::previewers::xcf::render;

fn fixture(name: &str) -> Vec<u8> {
    let path = format!("{}/tests/fixtures/xcf/{name}", env!("CARGO_MANIFEST_DIR"));
    std::fs::read(&path).unwrap_or_else(|e| panic!("{path}: {e}"))
}

fn reference(name: &str) -> RgbaImage {
    image::load_from_memory(&fixture(&format!("{name}.png")))
        .unwrap()
        .to_rgba8()
}

/// Mean absolute difference over premultiplied RGBA, in 0..=255 units, so
/// the colour of fully transparent pixels doesn't count.
fn mad(a: &RgbaImage, b: &RgbaImage) -> f64 {
    assert_eq!(a.dimensions(), b.dimensions());
    let mut sum = 0.0;
    for (p, q) in a.pixels().zip(b.pixels()) {
        let (pa, qa) = (f64::from(p[3]) / 255.0, f64::from(q[3]) / 255.0);
        for k in 0..3 {
            sum += (f64::from(p[k]) * pa - f64::from(q[k]) * qa).abs();
        }
        sum += (f64::from(p[3]) - f64::from(q[3])).abs();
    }
    sum / (a.len() as f64)
}

fn check(name: &str) {
    let ours = render(&fixture(&format!("{name}.xcf")), 4096).unwrap();
    let d = mad(&ours, &reference(name));
    println!("{name}: {}x{} mad {d:.3}", ours.width(), ours.height());
    assert!(d < 0.25, "{name}: mean abs diff {d:.3}");
}

