#[test]
fn shrinks_without_upscaling() {
    let big = render(&fixture("rgb_layers.xcf"), 32).unwrap();
    assert_eq!(big.dimensions(), (32, 22));
    let small = render(&fixture("gray.xcf"), 1000).unwrap();
    assert_eq!(small.dimensions(), (40, 30));
}

#[test]
fn subsampled_shrink_is_close() {
    // max 20 on a 130 px canvas composites on a 3x point-sampled grid first.
    let ours = render(&fixture("rgb_layers.xcf"), 20).unwrap();
    let want = imageops::resize(&reference("rgb_layers"), 20, 14, imageops::FilterType::Triangle);
    let d = mad(&ours, &want);
    println!("subsampled: mad {d:.3}");
    assert!(d < 8.0, "mean abs diff {d:.3}");
}

fn assert_err_fast(bytes: &[u8]) {
    let t = Instant::now();
    assert!(render(bytes, 256).is_err());
    assert!(t.elapsed() < Duration::from_secs(1), "took {:?}", t.elapsed());
}

#[test]
fn empty_file() {
    assert_err_fast(b"");
}

#[test]
fn zero_max() {
    assert!(render(&fixture("gray.xcf"), 0).is_err());
}

#[test]
fn random_garbage() {
    let mut s = 0x2545_f491_4f6c_dd1du64;
    let mut noise = || {
        s ^= s << 13;
        s ^= s >> 7;
        s ^= s << 17;
        s as u8
    };
    for len in [1, 13, 14, 100, 4096, 100_000] {
        let junk: Vec<u8> = (0..len).map(|_| noise()).collect();
        assert_err_fast(&junk);
        // Garbage behind a valid magic exercises the parser proper.
        for magic in [&b"gimp xcf file\0"[..], b"gimp xcf v011\0", b"gimp xcf v003\0"] {
            assert_err_fast(&[magic, &junk].concat());
        }
    }
}

#[test]
fn huge_canvas() {
    let mut f = b"gimp xcf v011\0".to_vec();
    for v in [100_000u32, 100_000, 0, 150, 0, 0] {
        f.extend(v.to_be_bytes());
    }
    f.extend([0; 16]);
    assert_err_fast(&f);
}

/// A zlib XCF whose layers all share one layer record and whose tiles all
/// share one compressed tile: tiny on disk, huge to decode.
fn shared_tiles(w: u32, h: u32, layers: u32) -> Vec<u8> {
    use std::io::Write;
    let mut z = flate2::write::ZlibEncoder::new(Vec::new(), flate2::Compression::best());
    z.write_all(&[200, 100, 50, 255].repeat(4096)).unwrap();
    let tile = z.finish().unwrap();
    let ntiles = w.div_ceil(64) * h.div_ceil(64);
    let mut f = b"gimp xcf v008\0".to_vec();
    let put = |f: &mut Vec<u8>, v: &[u32]| v.iter().for_each(|v| f.extend(v.to_be_bytes()));
    put(&mut f, &[w, h, 0, 150, 17, 1]);
    f.push(2); // PROP_COMPRESSION: zlib
    put(&mut f, &[0, 0]);
    let layer = f.len() as u32 + 4 * (layers + 2);
    put(&mut f, &vec![layer; layers as usize]);
    put(&mut f, &[0, 0]);
    let hier = layer + 36;
    // RGBA, a 4-byte name, no properties, no mask.
    put(&mut f, &[w, h, 1, 4, u32::from_be_bytes(*b"L\0\0\0"), 0, 0, hier, 0]);
    let level = hier + 20;
    put(&mut f, &[w, h, 4, level, 0]);
    put(&mut f, &[w, h]);
    put(&mut f, &vec![level + 8 + 4 * (ntiles + 1); ntiles as usize]);
    put(&mut f, &[0]);
    f.extend(tile);
    f
}

#[test]
fn shared_tiles_render() {
    let img = render(&shared_tiles(2000, 1500, 1), 100).unwrap();
    assert_eq!(img.dimensions(), (100, 75));
    assert!(img.pixels().all(|p| p.0 == [200, 100, 50, 255]));
}

#[test]
fn decompression_bomb() {
    // 1000 layers x 100 MP from a ~100 KB file.
    let f = shared_tiles(10_000, 10_000, 1000);
    let t = Instant::now();
    let err = render(&f, 256).unwrap_err();
    assert!(err.contains("too much work"), "{err}");
    assert!(t.elapsed() < Duration::from_secs(10), "took {:?}", t.elapsed());
}

#[test]
fn truncated() {
    for name in ["rgb_layers.xcf", "zlib_half_linear.xcf", "v0_raw.xcf"] {
        let full = fixture(name);
        assert_err_fast(&full[..full.len() / 2]);
        // No prefix may panic or stall, whatever it returns.
        for cut in (0..full.len()).step_by(7) {
            let t = Instant::now();
            let _ = render(&full[..cut], 256);
            assert!(t.elapsed() < Duration::from_secs(1));
        }
    }
}

#[test]
fn corrupted_bytes_never_panic() {
    let mut s = 0x9e37_79b9_7f4a_7c15u64;
    let mut next = || {
        s ^= s << 13;
        s ^= s >> 7;
        s ^= s << 17;
        s
    };
    for name in [
        "rgb_layers.xcf",
        "group_mask.xcf",
        "zlib_half_linear.xcf",
        "indexed.xcf",
        "u16_gamma.xcf",
    ] {
        let orig = fixture(name);
        for _ in 0..500 {
            let mut f = orig.clone();
            for _ in 0..1 + next() % 4 {
                let at = (next() % f.len() as u64) as usize;
                f[at] = next() as u8;
            }
            let t = Instant::now();
            let _ = render(&f, 128);
            assert!(t.elapsed() < Duration::from_secs(2), "{name} took {:?}", t.elapsed());
        }
    }
}
